package cc.wuersan008.smartisanx.ui.asset

import androidx.annotation.DrawableRes
import cc.wuersan008.smartisanx.ui.R

/**
 * 一个原版图标条目。
 *
 * @param name 资源名，例如 `standard_icon_back_selector`
 * @param res 资源 id
 */
class SmartisanIconEntry(val name: String, @DrawableRes val res: Int)

/** 一组原版图标。 */
class SmartisanIconGroup(val title: String, val icons: List<SmartisanIconEntry>)

/**
 * **原版 UI 图标总表（只收录图标，不含按钮/面板底图）。**
 *
 * 全部来自原厂 APK 的 `res/drawable*`，按内容去重、保留原始文件名与夜间/多密度变体。
 *
 * 收录规则：把 selector 链解析到最底层的位图后，
 *
 * - **排除** 可拉伸的 nine-patch（`.9.png`）—— 那些是按钮、面板、行底图，不是图标；
 * - **排除** 单边超过 128px 的大图 —— 那些是插图、封面、背景；
 * - **排除** `<shape>` —— 那些是纯色/圆角底图。
 *
 * 分组按原版自己的命名习惯还原使用场景（标题栏动作、底部标签栏、列表与菜单项……）。
 *
 * **横屏素材补了竖屏变体**：原版有 37 张图只放在 `drawable-land-xxhdpi/`（计算器的
 * `sin` / `cos` / `log` 等按键字符是横屏专属）。竖屏手机取不到这些资源，
 * `Resources.getDrawable` 会抛 `NotFoundException`，所以每张都往 `drawable-xxhdpi/`
 * 复制了一份作为竖屏回落；横屏仍然优先用原来的 `drawable-land-xxhdpi/`。
 */
object SmartisanIconSet {

